-- The C1 corpus (MoreCheese @ f3108c29ea) for the Prediction Unit gates. Test schema only.
CREATE TABLE [pstruth].[C1Person] ([ID] UNIQUEIDENTIFIER NOT NULL PRIMARY KEY, [JoinDate] DATE NULL, [Segment] NVARCHAR(50) NULL, [Region] NVARCHAR(50) NULL);
CREATE TABLE [pstruth].[C1OrderHeader] ([ID] UNIQUEIDENTIFIER NOT NULL PRIMARY KEY, [PersonID] UNIQUEIDENTIFIER NOT NULL, [OrderDate] DATE NOT NULL, [Status] NVARCHAR(20) NOT NULL, [OrderType] NVARCHAR(20) NOT NULL, [ReversesOrderID] UNIQUEIDENTIFIER NULL, [ReversedOn] DATE NULL);
CREATE TABLE [pstruth].[C1DuesPeriod] ([ID] UNIQUEIDENTIFIER NOT NULL PRIMARY KEY, [PersonID] UNIQUEIDENTIFIER NOT NULL REFERENCES [pstruth].[C1Person]([ID]), [PeriodIndex] INT NOT NULL, [OrderDate] DATE NOT NULL, [TierSKU] NVARCHAR(50) NOT NULL, [OrderID] UNIQUEIDENTIFIER NOT NULL, CONSTRAINT [UQ_C1DuesPeriod_Person_Period] UNIQUE ([PersonID], [PeriodIndex]));
CREATE TABLE [pstruth].[C1NonduesLine] ([ID] UNIQUEIDENTIFIER NOT NULL PRIMARY KEY, [PersonID] UNIQUEIDENTIFIER NOT NULL, [OrderID] UNIQUEIDENTIFIER NOT NULL, [OrderDate] DATE NOT NULL, [LineTotalNet] DECIMAL(18,2) NOT NULL, [ReversedOn] DATE NULL);
CREATE TABLE [pstruth].[C1EventAttendance] ([ID] UNIQUEIDENTIFIER NOT NULL PRIMARY KEY, [PersonID] UNIQUEIDENTIFIER NOT NULL, [EventDate] DATE NOT NULL);
CREATE TABLE [pstruth].[C1CourseCompletion] ([ID] UNIQUEIDENTIFIER NOT NULL PRIMARY KEY, [PersonID] UNIQUEIDENTIFIER NOT NULL, [CompletedOn] DATE NOT NULL);
CREATE TABLE [pstruth].[C1Certification] ([ID] UNIQUEIDENTIFIER NOT NULL PRIMARY KEY, [PersonID] UNIQUEIDENTIFIER NOT NULL, [AwardedOn] DATE NULL, [ExpiresOn] DATE NULL);
CREATE TABLE [pstruth].[C1CommitteeMembership] ([ID] UNIQUEIDENTIFIER NOT NULL PRIMARY KEY, [PersonID] UNIQUEIDENTIFIER NOT NULL, [StartDate] DATE NULL, [EndDate] DATE NULL);
